import {getDiscipline,disciplineLabel} from './disciplines.js';
import {translateUIEnglish} from './ui-english.js';
import {RELEASE_NOTES_VERSION,RELEASE_NOTES} from './release-notes.js';
import {renderPortrait} from './appearance.js';
const esc=value=>String(value??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const genderName=(gender,locale)=>({male:locale==='en'?'Male':'남성',female:locale==='en'?'Female':'여성',unspecified:locale==='en'?'Unspecified':'미지정'}[gender]);

export function renderOnboardingFlow({locale='ko'}={}){if(locale==='en')return EN_FLOW;return `<section class="onboarding-flow" aria-labelledby="onboarding-flow-heading"><h3 id="onboarding-flow-heading">먼저, 어디서 무엇을 하나요?</h3><p>전공 지식 없이도 플레이할 수 있습니다. 문제를 푸는 게임이 아니라 학생의 말과 수행 보고를 보고 일정·업무·연구비를 선택하는 게임입니다.</p><div class="onboarding-menu-map"><article><strong>학생 지도</strong><p>이번 달 주별 계획 · 교수 업무 · 연구실 예산</p></article><article><strong>연구 기록</strong><p>지난 수행과 연구 성과 · 저장점 보관·불러오기</p></article><article><strong>메일함</strong><p>지도 종료 뒤 편지 · 학생의 CV 다시 보기</p></article></div><ol class="onboarding-month-flow"><li>학생 제안을 듣고</li><li>일정·업무·예산을 정하고</li><li>한 달을 진행한 뒤</li><li>수행 보고로 다음 달을 고칩니다.</li></ol><section class="onboarding-funding-basics"><h4>연구비와 지출도 직접 계획합니다.</h4><ul><li>잔액이 부족해도 부족액을 자동 차입해 한 달을 진행합니다. 이후 입금으로 갚으며, 이자·행정 부담과 반복 차입 경고를 살펴야 합니다.</li><li>학생인건비 계상률은 3월, “연구환경”·“연구성과 지원”은 매달 조정합니다. 실험·분석 주수에 따라 소모품·활동비도 달라집니다.</li><li>학생인건비 풀은 급여 전용입니다. 연구비 신청은 “이번 달 추가 활동”에서 3월·9월에 하며, 학생의 휴식 요청과 수행 보고도 함께 봅니다.</li></ul></section><p class="small-note">첫 면담 뒤 실제 화면을 짧게 안내합니다. 건너뛰어도 되고, 상단 “플레이 안내”에서 언제든 다시 볼 수 있습니다. 연구비가 부족한 달도 차액을 자동 차입해 진행할 수 있습니다.</p></section>`;}

export function renderAdmissionInterview({candidates,profile,professorName,selected,locale='ko',releaseVersion=RELEASE_NOTES_VERSION}){if(locale==='en')return renderEnglishInterview({candidates,profile,professorName,selected,releaseVersion});return `<section class="welcome admission-interview"><h2>이번 학기 입학면접</h2><p>${esc(professorName)} · ${esc(getDiscipline(profile.fieldId).label)} · ${profile.labMode==='wet'?'Wet lab':'Dry lab'} · ${profile.difficulty==='beginner'?'신임교수(쉬움)':'현실(보통)'}</p><p>세 지원자의 성적, 관심 분야와 면접에서 나눈 이야기를 읽고 한 명을 선택하세요. 연구실 생활은 함께 지내며 알아갑니다.</p><form id="admission-form"><fieldset class="admission-candidates"><legend>지도할 학생 한 명 선택</legend>${candidates.map(c=>`<label class="candidate-option ${selected===c.index?'selected':''}"><input type="radio" name="candidateIndex" value="${c.index}" ${selected===c.index?'checked':''} required><article><div class="candidate-heading"><strong>${esc(c.name)}</strong><span>${genderName(c.gender,locale)} · 학점 ${c.gpa.toFixed(2)} / 4.5</span></div><dl><div><dt>관심 분야</dt><dd>${esc(c.interest)}</dd></div><div><dt>면접 인상</dt><dd>${esc(c.impression)}</dd></div></dl></article></label>`).join('')}</fieldset><p class="small-note">이번 면접의 후보는 새로고침해도 유지됩니다. 성적과 짧은 면접 인상이 학생의 모든 모습을 설명하지는 않습니다.</p><button type="submit" class="primary">선택한 학생과 첫 면담 시작 →</button></form><button type="button" class="text-button update-replay" data-ui="update-open">${esc(releaseVersion)} 변경사항 다시 보기 →</button></section>`;}

export function renderUpdateNotice({version=RELEASE_NOTES_VERSION,title=RELEASE_NOTES.title,changes=RELEASE_NOTES.changes,locale='ko'}={}){if(locale==='en')return renderEnglishUpdates({version});return `<div class="screen-guide-top"><span>이번 업데이트 · ${esc(version)}</span><button class="text-button" type="button" data-ui="update-close" aria-label="업데이트 안내 닫기">닫기</button></div><div class="update-notice-body"><h2 id="update-notice-title">${esc(title)}</h2><ul>${changes.map(text=>`<li>${esc(text)}</li>`).join('')}</ul><p>학생 지도와 연구실 운영이 조금 더 이해하기 쉽도록 점검하고 보수했습니다.</p></div><button class="primary" type="button" data-ui="update-close">알겠어요 · 시작 준비하기 →</button>`;}

const EN_FLOW=`<section class="onboarding-flow" aria-labelledby="onboarding-flow-heading"><h3 id="onboarding-flow-heading">Welcome to your faculty dashboard</h3><p>You do not need specialist knowledge. Read your student's comments and progress reports, then decide how to balance advising, research, time and funding.</p><div class="onboarding-menu-map"><article><strong>My lab</strong><p>Weekly plans · faculty responsibilities · lab budget</p></article><article><strong>Records</strong><p>Research progress · milestones · saved checkpoints</p></article><article><strong>Alumni</strong><p>Letters after advising ends · your student's CV</p></article></div><ol class="onboarding-month-flow"><li>Listen to the student's proposal</li><li>Agree on a plan and budget</li><li>Advance one month</li><li>Review what happened and adjust</li></ol><section class="onboarding-funding-basics"><h4>Plan your funding and expenses</h4><ul><li>If your operating balance runs out, a departmental advance covers the shortfall so you can continue. Incoming funding repays it automatically; interest, administrative strain and repeated borrowing still matter.</li><li>Review stipend allocation each September. Adjust research supplies and project support every month; experiment and analysis weeks also affect expenses.</li><li>The stipend reserve is restricted to student pay. Apply for grants through Additional faculty activity in March or September. Also check rest requests and progress reports.</li></ul></section><p class="small-note">A short guide walks through the actual dashboard after your first meeting. Skip it or reopen it through Play guide. This U.S. edition starts in September. Dollar amounts and academic rules are illustrative game settings, not institutional policy.</p></section>`;
function renderEnglishInterview({candidates,profile,professorName,selected,releaseVersion}){return `<section class="welcome admission-interview"><h2>Fall research intake</h2><p><span data-user-text>${esc(professorName)}</span> · ${esc(disciplineLabel(profile.fieldId,'en'))} · ${profile.labMode==='wet'?'Wet lab':'Dry lab'} · ${profile.difficulty==='beginner'?'New faculty (easy)':'Realistic (standard)'}</p><p>Read three applicants' transcripts, research interests and interview impressions. Choose one student; their habits and needs will become clearer as you work together.</p><form id="admission-form"><fieldset class="admission-candidates"><legend>Choose one student to advise</legend>${candidates.map(c=>`<label class="candidate-option ${selected===c.index?'selected':''}"><input type="radio" name="candidateIndex" value="${c.index}" ${selected===c.index?'checked':''} required><article><div class="candidate-heading">${c.appearance?`<span class="candidate-portrait">${renderPortrait(c.appearance)}</span>`:""}<strong>${esc(c.name)}</strong><span>${genderName(c.gender,'en')} · GPA ${c.gpa.toFixed(2)} / 4.0</span></div><dl><div><dt>Research interests</dt><dd>${esc(translateUIEnglish(c.interest))}</dd></div><div><dt>Interview impression</dt><dd>${esc(translateUIEnglish(c.impression))}</dd></div>${c.background?`<div class="candidate-background"><dt>In their own words</dt><dd>${esc(c.background.body)}</dd></div>`:""}</dl></article></label>`).join('')}</fieldset><p class="small-note">Reloading keeps the same applicants. A transcript and a brief interview do not reveal everything about a student.</p><button type="submit" class="primary">Begin advising the selected student →</button></form><button type="button" class="text-button update-replay" data-ui="update-open">Review ${esc(releaseVersion)} updates →</button></section>`;}
function renderEnglishUpdates({version}){return `<div class="screen-guide-top"><span>What's new · ${esc(version)}</span><button class="text-button" type="button" data-ui="update-close" aria-label="Close update notice">Close</button></div><div class="update-notice-body"><h2 id="update-notice-title">Evolving hairstyles and automatic analytics cleanup</h2><ul><li>Campus hairstyles now include natural dark, brown, blond and auburn tones with straight, wavy or coily texture. Some early undergraduates have peekaboo or bleached color, which returns to a natural palette after the undergraduate phase. Hair grows over time, with rare long-haired or hairless cosmetic variants. These visuals do not change abilities or infer identity from names or backgrounds. New U.S. applicants have more diverse names, appearances and self-described educational journeys. Background does not change ability or research outcomes.</li><li>The first conversation begins with “What do you think?” before planning the next step together.</li><li>Standard mode now includes limited support for essential shortfalls in the first two years. Automatic departmental advances remain available.</li><li>A 30-minute faculty portal countdown can be extended. Its playful sign-out preserves your game for reconnection.</li><li>Korean names are more varied, while existing students and shared applicants stay the same. Mobile guidance keeps the controls clear. Weekly activity results and week labels now render fully in English. Newly consented Sites analytics are retained for up to five years and tagged as Korean or North American edition. Expired analytics are automatically deleted by a daily cloud task at 3 a.m. Korea time even with no visitors. Previous 90-day analytics consent is reset and earlier-policy analytics are discarded; game progress, letters and checkpoints are preserved. GitHub/local analytics stay on the device with no automatic upload. The lab sofa now follows the floor perspective, with an open front and a properly seated student.</li></ul><p>The academic system and dollar budgets are fictional settings inspired by U.S. research universities.</p></div><button class="primary" type="button" data-ui="update-close">Got it · prepare to begin →</button>`;}
